/**
 * @method
 * @name bitrue#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://github.com/Bitrue-exchange/Spot-official-api-docs#test-connectivity
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Bitrue) FetchStatusAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Bitrue) fetchStatusBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.SpotV1PublicGetPing(params))
	PanicOnError(response)
	//
	// empty means working status.
	//
	//     {}
	//
	var keys []string = ObjectKeys(response)
	var keysLength int = GetArrayLength(keys)
	var formattedStatus any = Ternary(IsTrue((IsGreaterThan(keysLength, 0))), "maintenance", "ok")

	ch <- map[string]any{
		"status":  formattedStatus,
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	}
	return nil
}

